using System.Data.Entity;
namespace MyStoreCustomer.Models { public class StoreDbContext:DbContext { public StoreDbContext():base("MyStoreCustomer"){} public DbSet<Customer> Customers{get;set;} public DbSet<Product> Products{get;set;} public DbSet<StoreOrder> Orders{get;set;} public DbSet<OrderDetail> OrderDetails{get;set;} public DbSet<AppUser> Users{get;set;} protected override void OnModelCreating(DbModelBuilder b){b.Entity<Customer>().ToTable("Customer");b.Entity<Product>().ToTable("Product");b.Entity<StoreOrder>().ToTable("Order");b.Entity<OrderDetail>().ToTable("OrderDetail");b.Entity<AppUser>().ToTable("User");b.Entity<StoreOrder>().Property(x=>x.TotalAmount).HasPrecision(18,2);b.Entity<OrderDetail>().Property(x=>x.UnitPrice).HasPrecision(18,2);base.OnModelCreating(b);} } }